import { CheckboxGroup } from '@absoluteui/components/checkbox-group';

const host = document.createElement('div');
document.body.append(host);
CheckboxGroup.create(host, {
  label: 'Notifications',
  name: 'notify',
  description: 'Choose at least one channel.',
  required: true,
  options: [
    { value: 'email', label: 'Email' },
    { value: 'sms', label: 'SMS', description: 'Carrier rates may apply' },
    { value: 'push', label: 'Push notification' },
  ],
});

import { CheckboxGroup } from '@absoluteui/components/checkbox-group';

const host = document.createElement('div');
document.body.append(host);
const topics = CheckboxGroup.create(host, {
  label: 'Topics',
  orientation: 'horizontal',
  minSelected: 2,
  maxSelected: 3,
  options: ['Design', 'Security', 'Performance', 'Accessibility'].map((t) => ({ value: t.toLowerCase(), label: t })),
});
host.addEventListener('aui-change', () => {
  host.dataset.count = String(topics.value.length);
});
